window.ServiceMarketplaceOfflineMap=function(el,opts){opts=opts||{};let marker=null;function clamp(v,min,max){return Math.max(min,Math.min(max,v))}function xyFromLatLng(lat,lng){return{x:((lng+180)/360)*el.clientWidth,y:((90-lat)/180)*el.clientHeight}}function latLngFromEvent(e){const r=el.getBoundingClientRect();const x=clamp(e.clientX-r.left,0,r.width),y=clamp(e.clientY-r.top,0,r.height);return{lat:90-(y/r.height)*180,lng:(x/r.width)*360-180}}function place(ll){if(!marker){marker=document.createElement('div');marker.className='offline-map-marker';marker.draggable=!opts.readonly;el.appendChild(marker);if(!opts.readonly){marker.addEventListener('dragend',ev=>place(latLngFromEvent(ev)))}}const p=xyFromLatLng(ll.lat,ll.lng);marker.style.left=p.x+'px';marker.style.top=p.y+'px';opts.onChange&&opts.onChange(ll)}el.classList.add('offline-map');el.innerHTML='<div class="offline-map-crosshair"></div><div class="offline-map-label">'+(opts.readonly?'موقع مقدم الخدمة':'خريطة محلية مبسطة تعمل بدون إنترنت — انقر لتحديد الموقع')+'</div>';if(!opts.readonly){el.addEventListener('click',e=>place(latLngFromEvent(e)))}window.addEventListener('resize',()=>{if(opts.initial)place(opts.initial)});if(opts.initial)place(opts.initial);return{placeMarker:place}};
